        formRow.className = 'ai-assistant-fbk-popup-row';
        formRow.style.cursor = 'pointer';
        formRow.setAttribute('role', 'button');
        formRow.setAttribute('tabindex', '0');
        formRow.setAttribute('aria-label', 'Open detailed feedback form');

