            var _fbBase  = _EP.hasProfiles()
                ? (_EP.resolveEndpoint ? _EP.resolveEndpoint('feedback') : _EP.resolve('feedback'))
                : _resolveFlatFeatureEndpoint(cfg.panelFeedbackEndpoint || '', '/v1/feedback');
            var _fbToken = _EP.hasProfiles()
