        var snippetExpandedBtn = document.createElement('button');
        snippetExpandedBtn.type = 'button';
        snippetExpandedBtn.className = 'ai-assistant-panel-ep-snippet-mode';
        snippetExpandedBtn.setAttribute('aria-pressed', 'false');
