            pill.type = 'button';
            pill.className = 'ai-assistant-panel-ep-ext-pill';
            pill.setAttribute('role', 'switch');
            pill.setAttribute('aria-checked', isOn ? 'true' : 'false');
            if (pillId) pill.id = pillId;
